import{_ as a,o as i,c as t,a8 as r}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"Overview","description":"","frontmatter":{"title":"Overview","lang":"en"},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":1790353258000}'),l={name:"guide/overview.md"};function s(n,e,o,h,p,c){return i(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjJPdmVydmlldyUyMiUyQyUyMmxhbmclMjIlM0ElMjJlbiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzUzMjU4MDAwJTdE"},[...e[0]||(e[0]=[r(`<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>Handy, High performance Nginx firewall module.</p><h2 id="why-ngx-waf" tabindex="-1">Why ngx_waf <a class="header-anchor" href="#why-ngx-waf" aria-label="Permalink to &quot;Why ngx_waf&quot;">​</a></h2><ul><li>Basic protection: such as black and white list of IPs or IP range, uri black and white list, and request body black list, etc.</li><li>Easy to use: configuration files and rule files are easy to write and readable.</li><li>High performance: Efficient algorithms and caching.</li><li>Advanced protection: <a href="https://github.com/SpiderLabs/ModSecurity" target="_blank" rel="noreferrer">ModSecurity</a> compatible, you can use <a href="https://owasp.org/www-project-modsecurity-core-rule-set/" target="_blank" rel="noreferrer">OWASP(Open Web Application Security Project®) ModSecurity Core Rule Set</a>.</li><li>Friendly crawler verification: Supports verifying Google, Bing, Baidu and Yandex crawlers and allowing them automatically to avoid false positives.</li><li>Captcha: Supports three kinds of captchas: hCaptcha, reCAPTCHAv2 and reCAPTCHAv3.</li></ul><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><a href="https://github.com/SpiderLabs/ModSecurity" target="_blank" rel="noreferrer">ModSecurity</a> compatible. This feature is only available in the latest <code>Current</code> version.</li><li>Anti SQL injection (powered by <a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>).</li><li>Anti XSS (powered by <a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>).</li><li>IPV4 and IPV6 support.</li><li>Support for enabling CAPTCHAs, including <a href="https://www.hcaptcha.com/" target="_blank" rel="noreferrer">hCaptcha</a>, <a href="https://developers.google.com/recaptcha" target="_blank" rel="noreferrer">reCAPTCHAv2</a> and <a href="https://developers.google.com/recaptcha" target="_blank" rel="noreferrer">reCAPTCHAv3</a>. This feature is only available in the latest <code>Current</code> version.</li><li>Support authentication-friendly crawlers (based on user agent and IP identification) to avoid blocking of these crawlers (e.g. GoogleBot). This feature is only available in the latest <code>Current</code> version.</li><li>CC protection, if the request rate exceeds the limit, the IP will be automatically banned for a period of time, or use CAPTCHA to do human identification and allow it if successful..</li><li>Exceptional allow on specific IP address.</li><li>Block the specified IP or IP range.</li><li>Block the specified request body.</li><li>Exceptional allow on specific URL.</li><li>Block the specified URL.</li><li>Block the specified query string.</li><li>Block the specified UserAgent.</li><li>Block the specified Cookie.</li><li>Exceptional allow on specific Referer.</li><li>Block the specified Referer.</li></ul><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li>Telegram Channel: <a href="https://t.me/ngx_waf" target="_blank" rel="noreferrer">https://t.me/ngx_waf</a></li><li>Telegram Group (English): <a href="https://t.me/group_ngx_waf" target="_blank" rel="noreferrer">https://t.me/group_ngx_waf</a></li><li>Telegram Group (Chinese): <a href="https://t.me/group_ngx_waf_cn" target="_blank" rel="noreferrer">https://t.me/group_ngx_waf_cn</a></li></ul><h2 id="sponsor" tabindex="-1">Sponsor <a class="header-anchor" href="#sponsor" aria-label="Permalink to &quot;Sponsor&quot;">​</a></h2><p>Hope you can help promote this project. The more stars got, the better this project is. 😃</p><h2 id="test-suite" tabindex="-1">Test Suite <a class="header-anchor" href="#test-suite" aria-label="Permalink to &quot;Test Suite&quot;">​</a></h2><p>This module comes with a Perl-driven test suite. The test cases are declarative too. Thanks to the <a href="http://search.cpan.org/perldoc?Test::Nginx" target="_blank" rel="noreferrer">Test::Nginx</a> module in the Perl world.</p><p>To run it on your side:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">## It will take a lot of time, but it only needs to be run once.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cpan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Test::Nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># You need to specify a temporary directory.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If the directory does not exist it will be created automatically.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If the directory already exists it will be **removed** first and then created.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MODULE_TEST_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/temp/dir</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># You need to specify the absolute path to the dynamic module if you have it installed, </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># otherwise you do not need to run this line.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MODULE_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/ngx_http_waf_module.so</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./test/test-nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./init.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./start.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./t/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.t</span></span></code></pre></div><p>Some parts of the test suite requires standard modules proxy, rewrite and SSI to be enabled as well when building Nginx.</p><h2 id="performance-test" tabindex="-1">Performance Test <a class="header-anchor" href="#performance-test" aria-label="Permalink to &quot;Performance Test&quot;">​</a></h2><p><a href="./test.html#performance-test">Performance Test</a></p><h2 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to &quot;Thanks&quot;">​</a></h2><ul><li><a href="https://github.com/SpiderLabs/ModSecurity" target="_blank" rel="noreferrer">ModSecurity</a>: An open source, cross platform web application firewall (WAF) engine.</li><li><a href="https://github.com/troydhanson/uthash" target="_blank" rel="noreferrer">uthash</a>: C macros for hash tables and more.</li><li><a href="https://curl.se/libcurl/" target="_blank" rel="noreferrer">libcurl</a>: The multiprotocol file transfer library .</li><li><a href="https://github.com/DaveGamble/cJSON" target="_blank" rel="noreferrer">cJSON</a>: Ultralightweight JSON parser in ANSI C.</li><li><a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>: SQL / SQLI tokenizer parser analyzer.</li><li><a href="https://github.com/jedisct1/libsodium" target="_blank" rel="noreferrer">libsodium</a>: A modern, portable, easy to use crypto library.</li><li><a href="https://github.com/openresty/test-nginx" target="_blank" rel="noreferrer">test-nginx</a>: Data-driven test scaffold for Nginx C module and OpenResty Lua library development.</li><li><a href="https://github.com/dvershinin/lastversion" target="_blank" rel="noreferrer">lastversion</a>: A command line tool that helps you download or install a specific version of a project.</li><li><a href="https://github.com/loveshell/ngx_lua_waf" target="_blank" rel="noreferrer">ngx_lua_waf</a>: A web application firewall based on the lua-nginx-module (openresty).</li><li><a href="https://github.com/taobao/nginx-book" target="_blank" rel="noreferrer">nginx-book</a>: The Chinese language development guide for nginx.</li><li><a href="https://github.com/baishancloud/nginx-development-guide" target="_blank" rel="noreferrer">nginx-development-guide</a>: The Chinese language development guide for nginx.</li></ul>`,19)])])}const g=a(l,[["render",s]]);export{u as __pageData,g as default};
